<?php
require_once __DIR__.'/../includes/database.php';require_once __DIR__.'/../includes/team-inventory.php';
function inv_check($ok,$why){if(!$ok)throw new RuntimeException($why);}function inv_denied($fn,$status){try{$fn();}catch(CatalogException $e){inv_check($e->status===$status,$e->getMessage());return;}throw new RuntimeException('Expected rejection');}
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);initialize_database($db);foreach(['Admin','Encargado','Operador','Ajeno','Repo Owner'] as $i=>$n)stock_query($db,'INSERT INTO users(name,public_name,email,password_hash) VALUES(?,?,?,?)',[$n,$n,'inv'.$i.'@example.invalid','unused']);foreach([1,2] as $id)stock_query($db,'INSERT INTO stock_branches(owner_id,name,address,locality,province) VALUES(1,?,?,?,?)',['Branch '.$id,'A','B','C']);stock_query($db,"INSERT INTO branch_workspaces(owner_id,name) VALUES(1,'Company')");stock_query($db,'INSERT INTO branch_workspace_locations(branch_id,workspace_id) VALUES(1,1),(2,1)');stock_query($db,"INSERT INTO branch_team_members(branch_id,user_id,role) VALUES(1,2,'manager'),(1,3,'operator')");
for($i=0;$i<36;$i++){$code=(string)(10000000+$i);stock_query($db,'INSERT INTO pallet_labels(code,reserved_by,reserved_until) VALUES(?,5,?)',[$code,time()+3600]);$p=stock_claim($db,$code,5);stock_query($db,'UPDATE pallets SET branch_id=1 WHERE id=?',[$p['id']]);stock_save_product($db,5,['pallet_id'=>$p['id'],'ean'=>'96385074','name'=>'Producto lote '.$i,'amount'=>$i+1,'expires'=>'2030-01-01']);team_event($db,1,1,'member_role_changed',2);stock_query($db,'INSERT INTO pallet_activity(user_id,pallet_id,action,metadata) VALUES(1,?,?,?)',[$p['id'],'quantity_updated',json_encode(['ean'=>'96385074','old'=>0,'new'=>$i+1,'reference'=>'Lote único '.$i])]);}
$first=team_inventory_page($db,2,1,'palets',[]);inv_check(count($first['items'])===30&&$first['next_offset']===30,'first pallet page');$last=team_inventory_page($db,2,1,'palets',['offset'=>'30']);inv_check(count($last['items'])===6&&$last['next_offset']===null,'second pallet page');inv_check(count(team_inventory_page($db,2,1,'palets',['q'=>'10000035'])['items'])===1,'search beyond first page');inv_check(count(team_inventory_page($db,2,1,'palets',['q'=>'Repo Owner'])['items'])===30,'owner search');inv_check(team_inventory_page($db,2,1,'palets',['q'=>'%'])['items']===[],'literal wildcard');inv_check(team_inventory_page($db,2,1,'palets',['q'=>"' OR 1=1 --"])['items']===[],'SQL literal');
$goods=team_inventory_page($db,1,1,'mercaderia',[])['items'];inv_check(count($goods)===1&&(int)$goods[0]['units']===666&&(int)$goods[0]['pallets']===36,'EAN and expiry totals across all pallets');$lots=team_inventory_page($db,2,1,'lotes',['ean'=>'96385074','expires'=>'2030-01-01']);inv_check(count($lots['items'])===30&&$lots['next_offset']===30,'lots paginated');inv_check(count(team_inventory_page($db,2,1,'lotes',['ean'=>'96385074','expires'=>'2030-01-01','offset'=>'30'])['items'])===6,'lot second page');inv_check(team_inventory_page($db,2,1,'mercaderia',['expiry'=>'expired'])['items']===[],'expiry filter');
$events=team_inventory_page($db,2,1,'administracion',['offset'=>'30','action'=>'member_role_changed']);inv_check(count($events['items'])===6,'administration pagination');inv_check(count(team_inventory_page($db,2,1,'movimientos',['record'=>'1'])['items'])===1,'old movement detail');inv_check(team_inventory_page($db,2,1,'movimientos',['action'=>'product_removed'])['items']===[],'movement action filter');inv_check(count(team_inventory_page($db,2,1,'movimientos',['q'=>'Lote único 35'])['items'])===1,'metadata search');
foreach(['palets','mercaderia','lotes','movimientos','administracion'] as $view){inv_denied(fn()=>team_inventory_page($db,3,1,$view,[]),403);inv_denied(fn()=>team_inventory_page($db,4,1,$view,[]),403);inv_denied(fn()=>team_inventory_page($db,2,2,$view,[]),403);}inv_denied(fn()=>team_inventory_page($db,2,1,'movimientos',['from'=>'2026-02-30']),422);inv_denied(fn()=>team_inventory_page($db,2,1,'palets',['offset'=>'-1']),422);inv_denied(fn()=>team_inventory_page($db,2,1,'palets',['q'=>[]]),422);team_change_role($db,1,1,3,'manager',1);$audit=team_inventory_page($db,1,1,'administracion',['action'=>'member_role_changed'])['items'][0]['metadata'];inv_check($audit['old_role']==='operator'&&$audit['new_role']==='manager','role audit before and after');stock_query($db,'UPDATE branch_team_members SET expires_at=? WHERE user_id=2',[time()-1]);inv_denied(fn()=>team_inventory_page($db,2,1,'mercaderia',[]),403);echo "OK: all-branch filters, pagination, EAN/expiry totals and lot breakdown, old movement detail, literals, roles and expiry.\n";
